/**
 * Only the browser that generated the statement can notarize it. A shared link reads the statement and its exports but cannot write a proof to it.
 * @summary Memo payload the wallet signs to notarize the statement
 */
export const PrepareNotarizationParams = zod.object({
  "statementId": zod.coerce.string()
})

export const PrepareNotarizationQueryParams = zod.object({
  "payer": zod.coerce.string().optional().describe('Wallet public key that will pay for the memo transaction. When present the response includes an unsigned transaction.')
})

export const PrepareNotarizationResponse = zod.object({
  "statementId": zod.string(),
  "hash": zod.string(),
  "memo": zod.string().describe('Exact UTF-8 memo the wallet must sign'),
  "memoProgramId": zod.string(),
  "cluster": zod.string(),
  "mode": zod.enum(['onchain', 'simulated']),
  "instructions": zod.string(),
  "transaction": zod.string().nullable().describe('Base64 encoded unsigned versioned transaction containing the memo, present when payer was supplied and mode is onchain'),
  "lastValidBlockHeight": zod.number().int().nullable(),
  "proof": zod.object({
  "status": zod.enum(['none', 'pending', 'confirmed', 'failed', 'simulated']),
  "kind": zod.enum(['onchain_memo', 'simulated', 'none']),
  "hash": zod.string(),
  "memo": zod.string(),
  "signature": zod.string().nullable(),
  "slot": zod.number().int().nullable(),
  "signer": zod.string().nullable(),
  "confirmedAt": zod.coerce.date().nullable(),
  "explorerUrl": zod.string().nullable(),
  "message": zod.string()
})
})


/**
 * Only the browser that generated the statement can notarize it.
 * @summary Record a signed memo transaction or create a simulated proof
 */
export const SubmitNotarizationParams = zod.object({
  "statementId": zod.coerce.string()
})

export const SubmitNotarizationBody = zod.object({
  "signature": zod.string().nullish().describe('Signature of the memo transaction sent by the wallet'),
  "simulate": zod.boolean().describe('Create a clearly labeled simulated proof instead of verifying on chain')
})

export const SubmitNotarizationResponse = zod.object({
  "status": zod.enum(['none', 'pending', 'confirmed', 'failed', 'simulated']),
  "kind": zod.enum(['onchain_memo', 'simulated', 'none']),
  "hash": zod.string(),
  "memo": zod.string(),
  "signature": zod.string().nullable(),
  "slot": zod.number().int().nullable(),
  "signer": zod.string().nullable(),
  "confirmedAt": zod.coerce.date().nullable(),
  "explorerUrl": zod.string().nullable(),
  "message": zod.string()
})


